#include <thread>
#include <chrono>

void task(std::stop_token stoken) {
    while (!stoken.stop_requested()) {
        // Do work...
    }
}

int main() {
    std::jthread jt(task); // Automatically joins and supports cooperative cancellation
}

std::latch workDone(4);
// Worker finishes work
workDone.___();
